def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    reqs = [WATER_REQ]
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0.0)))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 20.0))

    total_req = 0.0
    for r in reqs:
        total_req += float(r)
    scarcity = supply / total_req if total_req > 0 else 1.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_prev = sorted_bids[int(1)]
    elif len(prev_bids) == 1:
        second_prev = prev_bids[int(0)]

    danger = 0
    if hp <= 2 or no_water >= 2:
        danger = 3
    elif hp <= 4 or no_water >= 1:
        danger = 2
    elif hp <= 6:
        danger = 1

    if danger == 3:
        target = max(150.0, highest_prev + 3.0)
    elif danger == 2:
        target = max(132.0, second_prev + 2.0, highest_prev * 0.92)
    else:
        if scarcity >= 0.95:
            target = 18.0
        elif scarcity >= 0.75:
            target = 42.0
        elif scarcity >= 0.55:
            target = 68.0
        else:
            target = 96.0

        if highest_prev >= 145.0:
            target = min(target, 58.0)
        elif highest_prev >= 120.0:
            target = min(target, 72.0)
        else:
            target = max(target, highest_prev + 1.5 if highest_prev > 0 else 40.0)

    if budget < target:
        if danger >= 2:
            target = budget
        else:
            target = min(budget, max(12.0, budget * 0.55))

    reserve_floor = DAILY_SALARY * max(0, 9 - int(day_context['day'])) * 0.18
    if danger == 0 and budget - target < reserve_floor:
        target = max(10.0, budget - reserve_floor)

    if target < 0:
        target = 0.0
    if target > budget:
        target = budget
    return float(round(target, 2))

