def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no one alive, take what you can afford.
    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.6))

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    # Read yesterday's bids from previous_trace only (immediate reaction).
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate pressure from opponents: use yesterday max/median.
    if prev_bids:
        prev_max = max(prev_bids)
        prev_med = sorted(prev_bids)[len(prev_bids)//2]
    else:
        prev_max = 0.0
        prev_med = 0.0

    # Base bid target: stay below Cindy/Bob top but above typical mid.
    # Scale with how urgent water is for us.
    urgency = 0
    if my_no_water_days >= 2:
        urgency = 2
    elif my_no_water_days == 1:
        urgency = 1

    # Supply heuristic: lower supply increases competition.
    supply_factor = 1.0
    if supply <= 17.0:
        supply_factor = 1.15
    elif supply >= 22.0:
        supply_factor = 0.95

    # If my HP is low, bid aggressively to avoid death.
    if my_hp <= 2.0 or urgency == 2:
        target = min(my_budget, (DAILY_SALARY * 0.95) * supply_factor)
        # If opponents were bidding extremely high yesterday, still try to outbid slightly.
        if prev_max > DAILY_SALARY * 0.85:
            target = min(my_budget, max(target, prev_med + 10.0))
        return max(0.0, target)

    # Otherwise, bid moderately: enough to beat typical bids but not match max.
    # If opponents were generally high yesterday, raise our floor.
    if prev_med >= DAILY_SALARY * 0.75:
        base = DAILY_SALARY * 0.70
    else:
        base = DAILY_SALARY * 0.55

    # Add a small increment over median to improve winning chance.
    target = base * supply_factor
    if prev_med > 0.0:
        target = max(target, prev_med + 5.0)

    # Cap to avoid overspending; keep some budget for later days.
    # Also avoid exceeding yesterday max by too much.
    cap = min(my_budget, prev_max * 0.92) if prev_max > 0.0 else my_budget
    target = min(target, cap)

    # If we still might be underbidding vs very high max yesterday, bump slightly.
    if prev_max > DAILY_SALARY * 0.9 and target < prev_max * 0.85:
        target = min(my_budget, prev_max * 0.88)

    return max(0.0, float(target))
